/**
 * Importer fixture tests for the two-group rework (docs/16, migration 0011).
 *
 * Fixtures are generated by scripts/make-importer-fixtures.py into ~/fixtures.
 * Run against a bundled copy of src/lib/importer.ts:
 *
 * Bundle next to the script so Node can still resolve read-excel-file from
 * node_modules, then run it from the repo root:
 *
 *   npx esbuild src/lib/importer.ts --bundle --platform=node --format=esm \
 *     --outfile=importer.bundle.mjs --alias:@=./src --external:read-excel-file
 *   node scripts/test-importer-groups.mjs
 *
 * The case that matters most is 10: a coach still holding the OLD one-column
 * template must keep importing, with their plans landing on the distance
 * schedule and nobody's training group touched.
 */
import { readFileSync, readdirSync } from "node:fs";
import { parseTemplate } from "./importer.bundle.mjs";
const DIR = process.env.HOME + "/fixtures";
let pass = 0, fail = 0;
const ok = (c, m) => { if (c) { pass++; } else { fail++; console.log("   ✗ " + m); } };
const P = async (f) => parseTemplate(readFileSync(`${DIR}/${f}`));

const w = (r) => r.ok ? r.data.warnings.map(x => `${x.where}: ${x.message}`).join(" | ") : "";
const e = (r) => r.ok ? "" : r.errors.map(x => `${x.where}: ${x.message}`).join(" | ");

let r = await P("01_normal.xlsx");
console.log("01 normal:", r.ok ? "parsed" : e(r));
ok(r.ok, "01 should parse");
if (r.ok) {
  ok(r.data.weekStartISO === "2026-09-07", "01 monday");
  ok(r.data.plansDistance[1] === "6x1mi @ threshold", "01 distance tue");
  ok(r.data.plansMid[1] === "8x400 @ 3k", "01 mid tue");
  const g = Object.fromEntries(r.data.goals.map(x => [x.email, x]));
  const es = r.data.goals.map(x => x.email);
  ok(r.data.goals.length === 4, "01 four goal rows, got " + r.data.goals.length);
  ok(r.data.goals.filter(x => x.group === "mid").length === 2, "01 two mid");
  ok(r.data.goals.filter(x => x.group === "distance").length === 1, "01 one distance");
  ok(r.data.goals.filter(x => x.group === null).length === 1, "01 one null group");
  const range = r.data.goals.find(x => x.label === "55-60");
  ok(range && range.goal === 57.5, "01 range midpoint");
  const plus = r.data.goals.find(x => x.label === "60+");
  ok(plus && plus.goal === 60, "01 plus floor");
}

r = await P("02_bad_group.xlsx");
console.log("02 bad group:", r.ok ? "PARSED (should not)" : e(r));
ok(!r.ok, "02 should reject");
ok(!r.ok && /Goals!D2/.test(e(r)) && /Middle-ish/.test(e(r)), "02 names the cell and the value");

r = await P("03_mid_no_plan.xlsx");
ok(r.ok, "03 should parse");
console.log("03 mid w/o plan warnings:", w(r));
ok(r.ok && /marked Mid-D.*mid-distance column is empty/i.test(w(r)), "03 warns mid-D has no workouts");

r = await P("04_plan_no_mid.xlsx");
ok(r.ok, "04 should parse");
console.log("04 plan w/o mid warnings:", w(r));
ok(r.ok && /nobody in this file is marked Mid-D/i.test(w(r)), "04 warns nobody is mid");

r = await P("05_group_no_goal.xlsx");
ok(r.ok, "05 should parse");
if (r.ok) {
  const row = r.data.goals[0];
  ok(r.data.goals.length === 1, "05 keeps the group-only row, got " + r.data.goals.length);
  ok(row && row.goal === null, "05 goal is null");
  ok(row && row.group === "mid", "05 group survives");
  ok(/no mileage in column C/i.test(w(r)), "05 still reports the blank mileage");
  ok(r.data.warnings.filter(x => /no mileage/i.test(x.message)).length === 1, "05 blank-mileage warnings are collapsed to one");
}

r = await P("06_no_distance.xlsx");
ok(r.ok, "06 should parse");
console.log("06 no distance warnings:", w(r));
ok(r.ok && /distance column is empty/i.test(w(r)), "06 warns empty distance column");

r = await P("07_variants.xlsx");
ok(r.ok, "07 variants should parse: " + e(r));
if (r.ok) {
  const gs = r.data.goals.map(x => x.group);
  ok(JSON.stringify(gs) === JSON.stringify(["mid","mid","distance","mid"]), "07 spellings normalise, got " + JSON.stringify(gs));
}

r = await P("08_not_monday.xlsx");
ok(!r.ok, "08 non-Monday rejected");
ok(!r.ok && /Week Plan!B3/.test(e(r)), "08 names B3");

r = await P("09_blank_template.xlsx");
ok(!r.ok || r.data.goals.length === 0, "09 shipped blank template has no goals");
console.log("09 blank template:", r.ok ? `parsed, ${r.data.goals.length} goals, warnings: ${w(r)}` : e(r));

// ---- the one that matters most: a coach still holding the OLD file ----
r = await P("10_legacy_v1_filled.xlsx");
console.log("10 legacy v1:", r.ok ? "parsed" : e(r));
ok(r.ok, "10 legacy v1 file still imports");
if (r.ok) {
  ok(r.data.plansDistance[0] === "TR + drills", "10 v1 plans land in the distance column");
  ok(r.data.plansMid.every(t => t === ""), "10 v1 gives empty mid plans");
  ok(r.data.goals.length === 2, "10 v1 goals parsed, got " + r.data.goals.length);
  ok(r.data.goals.every(g => g.group === null), "10 v1 changes nobody's group");
}

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
